using Sigov.Application.Agro.Permissions; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Application.Agro.ComprasAgriculturaFamiliar;
public sealed class AgroCompraAgriculturaFamiliarValidator{public Result Validar(AgroCompraAgriculturaFamiliarCreateRequest r){if(r.ProdutorId<=0)return Result.Failure("Compra exige produtor."); if(string.IsNullOrWhiteSpace(r.Produto))return Result.Failure("Compra exige produto."); if(r.Quantidade<=0)return Result.Failure("Quantidade deve ser maior que zero."); if(r.ValorUnitario<0)return Result.Failure("Valor unitário não pode ser negativo."); return Result.Success();} public decimal Calcular(AgroCompraAgriculturaFamiliarCreateRequest r)=>r.Quantidade*r.ValorUnitario;}
public sealed class AgroCompraAgriculturaFamiliarService:IAgroCompraAgriculturaFamiliarService{private readonly IAgroAccessChecker _a;private readonly AgroCompraAgriculturaFamiliarValidator _v;private readonly IAgroCompraAgriculturaFamiliarRepository _r; public AgroCompraAgriculturaFamiliarService(IAgroAccessChecker a,AgroCompraAgriculturaFamiliarValidator v,IAgroCompraAgriculturaFamiliarRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.compras_agricultura_familiar"),ct); public async Task<Result<PagedResult<AgroCompraAgriculturaFamiliarResponse>>> ListarAsync(int page,int pageSize,CancellationToken ct){var c=await C(AgroPermissions.CompraAfVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroCompraAgriculturaFamiliarResponse>>.Failure(c.Error!); return Result<PagedResult<AgroCompraAgriculturaFamiliarResponse>>.Success(await _r.ListarAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.ExercicioId,page,pageSize,ct));} public async Task<Result<AgroCompraAgriculturaFamiliarResponse>> ObterAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.CompraAfVisualizar,ct); if(c.IsFailure)return Result<AgroCompraAgriculturaFamiliarResponse>.Failure(c.Error!); var row=await _r.ObterAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,ct); return row is null?Result<AgroCompraAgriculturaFamiliarResponse>.Failure("Compra da agricultura familiar não encontrada."):Result<AgroCompraAgriculturaFamiliarResponse>.Success(row);} public async Task<Result<long>> CriarAsync(AgroCompraAgriculturaFamiliarCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.CompraAfCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.ExercicioId,c.Value.UsuarioId,r,_v.Calcular(r),ct));} public async Task<Result> AtualizarAsync(long id,AgroCompraAgriculturaFamiliarCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.CompraAfEditar,ct); if(c.IsFailure)return Result.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return v; await _r.AtualizarAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.ExercicioId,c.Value.UsuarioId,r,_v.Calcular(r),ct); return Result.Success();} public async Task<Result> CancelarAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.CompraAfCancelar,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.CancelarAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,ct); return Result.Success();}}
